 53 | export function canTravel(from, to, objects = OBJECTS) {
 54 |   const steps = Math.max(1, Math.ceil(Math.hypot(to.x - from.x, to.y - from.y) / 0.07));
 55 |   for (let i = 0; i <= steps; i++) {
 56 |     const t = i / steps;
 57 |     if (!isWalkable(from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t, objects)) return false;
 58 |   }
 59 |   return true;
 60 | }
