 62 | // A* on a quarter-tile grid, followed by collision-tested line-of-sight smoothing.
 63 | export function nearestWalkable(tx, ty, objects = OBJECTS) {
 64 |   if (isWalkable(tx, ty, objects)) return { x: tx, y: ty };
 65 |   // Spiral outward in quarter-tile steps until we find a walkable point
 66 |   const step = 0.25;
 67 |   for (let r = step; r <= 3; r += step) {
 68 |     let best = null, bestDist = Infinity;
 69 |     const n = Math.ceil((r * 2) / step);
 70 |     for (let i = 0; i <= n; i++) {
 71 |       const t = i / n;
 72 |       for (const [cx, cy] of [
 73 |         [tx - r + t * r * 2, ty - r],
 74 |         [tx + r, ty - r + t * r * 2],
 75 |         [tx + r - t * r * 2, ty + r],
 76 |         [tx - r, ty + r - t * r * 2],
 77 |       ]) {
 78 |         const rx = Math.round(cx / step) * step;
 79 |         const ry = Math.round(cy / step) * step;
 80 |         if (!isWalkable(rx, ry, objects)) continue;
 81 |         const d = Math.hypot(rx - tx, ry - ty);
 82 |         if (d < bestDist) { best = { x: rx, y: ry }; bestDist = d; }
 83 |       }
 84 |     }
 85 |     if (best) return best;
 86 |   }
 87 |   return null;
 88 | }
