730 | 
731 |     /* ── Main deck shadow ── */
732 |     px(ctx,C.tmFrameD, p.x+Math.round(S*2), p.y+Math.round(H*0.18)+Math.round(S*2), W-Math.round(S*2), Math.round(H*0.62));
