734 |     /* ── Deck surface (the flat running platform) ── */
735 |     px(ctx,hot?C.tmFrameL:C.tmFrame, p.x, p.y+Math.round(H*0.18), W, Math.round(H*0.62));
736 |     /* deck face highlight */
737 |     px(ctx,C.tmDeck, p.x+Math.round(S), p.y+Math.round(H*0.22), W-Math.round(S*2), Math.round(H*0.54));
738 | 
739 |     /* ── Animated belt stripes (scroll forward = downward in top-down) ── */
740 |     const beltX=p.x+Math.round(S*2), beltW=W-Math.round(S*4);
741 |     const beltY=p.y+Math.round(H*0.25), beltH=Math.round(H*0.48);
742 |     px(ctx,C.tmBelt, beltX, beltY, beltW, beltH);
743 |     /* scrolling stripes — 4 stripes spaced evenly, animated by time */
744 |     const stripeCount=4, stripeH=Math.max(1,Math.round(S*1.5));
745 |     const beltScroll=this.reducedMotion?0:(time/180)%1;
746 |     for(let i=0;i<stripeCount+1;i++){
747 |       const rawY=beltY+((i/stripeCount+beltScroll)%1)*beltH;
748 |       const sy=Math.round(rawY);
749 |       if(sy>=beltY&&sy+stripeH<=beltY+beltH){
750 |         px(ctx,C.tmBeltStripe, beltX, sy, beltW, stripeH);
751 |       }
752 |     }
753 |     /* belt surface sheen */
754 |     px(ctx,'rgba(255,255,255,0.06)', beltX, beltY, beltW, Math.round(S*2));
755 | 
756 |     /* ── Front roller (bottom edge of deck) ── */
757 |     const rollerH=Math.max(3,Math.round(S*3));
758 |     const rollerY=p.y+Math.round(H*0.73);
759 |     px(ctx,C.tmRollerL, p.x, rollerY, W, rollerH);
760 |     px(ctx,'rgba(255,255,255,0.18)', p.x+Math.round(S), rollerY, W-Math.round(S*2), Math.round(rollerH*0.4));
761 | 
762 |     /* ── Back roller (top edge of deck, partially behind console) ── */
763 |     const backRollerY=p.y+Math.round(H*0.18);
764 |     px(ctx,C.tmRoller, p.x, backRollerY, W, Math.round(S*3));
765 | 
766 |     /* ── Side rails (two handrails running along each long edge) ── */
767 |     const railW=Math.max(3,Math.round(S*3));
768 |     const railY=p.y+Math.round(H*0.06), railH=Math.round(H*0.70);
769 |     /* left rail shadow */
770 |     px(ctx,C.tmFrameD, p.x+Math.round(S*1.5), railY+Math.round(S), railW, railH);
771 |     /* left rail */
772 |     px(ctx,hot?C.tmRailL:C.tmRail, p.x+Math.round(S*1.5), railY, railW, railH);
773 |     px(ctx,'rgba(255,255,255,0.20)', p.x+Math.round(S*1.5), railY, railW, Math.round(railH*0.12));
774 |     /* right rail shadow */
775 |     px(ctx,C.tmFrameD, W+p.x-Math.round(S*4)+Math.round(S), railY+Math.round(S), railW, railH);
776 |     /* right rail */
777 |     px(ctx,hot?C.tmRailL:C.tmRail, W+p.x-Math.round(S*4), railY, railW, railH);
778 |     px(ctx,'rgba(255,255,255,0.20)', W+p.x-Math.round(S*4), railY, railW, Math.round(railH*0.12));
779 | 
780 |     /* ── Console / display panel (top of treadmill, against wall) ── */
781 |     const conW=Math.round(W*0.60), conH=Math.max(4,Math.round(H*0.20));
782 |     const conX=cx-Math.round(conW/2), conY=p.y;
783 |     /* console shadow */
784 |     px(ctx,C.tmFrameD, conX+Math.round(S), conY+Math.round(S), conW, conH);
785 |     /* console body */
