 55 | export function canTravel(from, to, objects = OBJECTS) {
 56 |   const steps = Math.max(1, Math.ceil(Math.hypot(to.x - from.x, to.y - from.y) / 0.07));
 57 |   for (let i = 0; i <= steps; i++) {
 58 |     const t = i / steps;
 59 |     if (!isWalkable(from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t, objects)) return false;
 60 |   }
 61 |   return true;
 62 | }
