 64 | // A* on a quarter-tile grid, followed by collision-tested line-of-sight smoothing.
 65 | export function nearestWalkable(tx, ty, objects = OBJECTS) {
 66 |   if (isWalkable(tx, ty, objects)) return { x: tx, y: ty };
 67 |   // Spiral outward in quarter-tile steps until we find a walkable point
 68 |   const step = 0.25;
 69 |   for (let r = step; r <= 3; r += step) {
 70 |     let best = null, bestDist = Infinity;
 71 |     const n = Math.ceil((r * 2) / step);
 72 |     for (let i = 0; i <= n; i++) {
 73 |       const t = i / n;
 74 |       for (const [cx, cy] of [
 75 |         [tx - r + t * r * 2, ty - r],
 76 |         [tx + r, ty - r + t * r * 2],
 77 |         [tx + r - t * r * 2, ty + r],
 78 |         [tx - r, ty + r - t * r * 2],
 79 |       ]) {
 80 |         const rx = Math.round(cx / step) * step;
 81 |         const ry = Math.round(cy / step) * step;
 82 |         if (!isWalkable(rx, ry, objects)) continue;
 83 |         const d = Math.hypot(rx - tx, ry - ty);
 84 |         if (d < bestDist) { best = { x: rx, y: ry }; bestDist = d; }
 85 |       }
 86 |     }
 87 |     if (best) return best;
 88 |   }
 89 |   return null;
 90 | }
