function millionWin(){
  save();
  const overlay=$('#million-overlay');
  const day=state.day, workers=state.workers||[];
  const workerLine=workers.length>0?'With help from '+workers.map(w=>w.emoji+' '+w.name).join(' & ')+'.':'You did it alone. Respect.';
