 47 | export function isWalkable(x, y, objects = OBJECTS) {
 48 |   if (!Number.isFinite(x) || !Number.isFinite(y)) return false;
 49 |   const r = FOUNDER_RADIUS;
 50 |   if (x < r || y < r || x > ROOM.width - r || y > ROOM.depth - r) return false;
 51 |   const pad = 0.05;
 52 |   return !objects.some((o) => x > o.x - pad && x < o.x + o.w + pad && y > o.y - pad && y < o.y + o.d + pad);
 53 | }
