294 |     const value = JSON.parse(raw);
295 |     if (!value || value.version !== 3) return fresh;
296 |     if (value.founder && isWalkable(value.founder.x, value.founder.y)) fresh.founder = { x: value.founder.x, y: value.founder.y };
297 |     if (Number.isFinite(value.energy)) fresh.energy = Math.max(0, Math.min(100, value.energy));
298 |     if (Number.isFinite(value.elec))   fresh.elec   = Math.max(0, Math.min(100, value.elec));
299 |     if (Number.isFinite(value.minutes)) fresh.minutes = Math.max(540, Math.min(1079, value.minutes));
300 |     if (Number.isFinite(value.distance)) fresh.distance = Math.max(0, Math.min(100000, value.distance));
301 |     if (Array.isArray(value.completed)) fresh.completed = TASKS.filter((id) => id !== 'sleep' && value.completed.includes(id));
302 |     fresh.sound = value.sound === true;
303 |     fresh.lightOn = value.lightOn !== false; // default to true if missing
304 |     fresh.lampOn = value.lampOn !== false;   // default to true if missing
305 |     if (Number.isFinite(value.day)) fresh.day = Math.max(1, Math.min(10, value.day));
306 |     if (Number.isFinite(value.money)) fresh.money = Math.max(0, value.money);
307 |     if (Array.isArray(value.workers)) {
308 |       fresh.workers = value.workers.filter(w =>
309 |         w && typeof w.name === 'string' && typeof w.role === 'string' &&
310 |         Number.isFinite(w.earningsPerTick) && Number.isFinite(w.deskIndex)
311 |       ).map(w => ({ ...w, level: Number.isFinite(w.level) ? Math.max(1, Math.min(3, w.level)) : 1, onStrike: w.onStrike === true, strikeCountdown: Number.isFinite(w.strikeCountdown) ? Math.max(0, w.strikeCountdown) : 0 }))
312 |        .slice(0, 2); // max 2 workers
313 |     }
314 |     if (Array.isArray(value.founderUpgrades)) {
315 |       const validIds = new Set(['focus', 'speeddesk', 'deepwork']);
316 |       fresh.founderUpgrades = value.founderUpgrades.filter(id => validIds.has(id));
317 |     }
318 |     if (Number.isFinite(value.cerealStock)) fresh.cerealStock = Math.max(0, Math.min(3, Math.floor(value.cerealStock)));
319 |     if (Number.isFinite(value.treadmillSessions)) fresh.treadmillSessions = Math.max(0, Math.floor(value.treadmillSessions));
320 |     return fresh;
321 |   } catch { return fresh; }
322 | }

