   315	function updateUI(){
   316	  const ep=state.energy;
   317	  $('#energy-fill').style.width=ep+'%';$('#energy-fill').classList.toggle('low',ep<20);
   318	  $('#energy-value').textContent=Math.round(ep);$('#energy-bar').setAttribute('aria-valuenow',Math.round(ep));
   319	  const el=state.elec;
   320	  $('#elec-fill').style.width=el+'%';$('#elec-fill').classList.toggle('low',el<20);
   321	  $('#elec-value').textContent=Math.round(el);$('#elec-bar').setAttribute('aria-valuenow',Math.round(el));
   322	  $('#money-value').textContent='$'+Math.floor(state.money||0).toLocaleString();
   323	  $('#hud-day').textContent='DAY '+state.day+' / 10';
   324	  document.querySelectorAll('[data-task]').forEach(btn=>{const done=state.completed.includes(btn.dataset.task);btn.classList.toggle('complete',done);const dot=btn.querySelector('.hud-task-dot');if(dot)dot.style.background=done?'#58c858':'';});
   325	  $('#sound-button').setAttribute('aria-pressed',String(state.sound));
   326	  $('#sound-button').setAttribute('aria-label','Turn sound '+(state.sound?'off':'on'));
   327	  if(isCycling){
   328	    const pct=Math.min(100,pedalPower);
   329	    $('#pedal-fill').style.width=pct+'%';$('#pedal-val').textContent=Math.round(pct);
   330	    $('#pedal-bar').setAttribute('aria-valuenow',Math.round(pct));
   331	    const cl=$('#cycling-charge-label');
   332	    if(pedalPower<25)cl.textContent='GET UP TO SPEED';
   333	    else if(pedalPower<50)cl.textContent='CHARGING \u26a1';
   334	    else if(pedalPower<75)cl.textContent='DOUBLE CHARGE \u26a1\u26a1';
   335	    else if(pedalPower<100)cl.textContent='TRIPLE CHARGE \u26a1\u26a1\u26a1';
   336	    else cl.textContent='OVERLOAD! STOP NOW \ud83d\udd25';
   337	    const pf=$('#pedal-fill');
   338	    pf.className='pedal-fill'+(pedalPower>=100?' broken':pedalPower>=75?' triple':pedalPower>=50?' double':pedalPower>=25?' normal':'');
   339	    $('#cycling-overlay').classList.toggle('overloaded',pedalPower>=100);
   340	  }
   341	  if(isTreadmilling){
   342	    const pct=Math.min(100,runPower);
   343	    $('#run-fill').style.width=pct+'%';$('#run-val').textContent=Math.round(pct);
   344	    $('#run-bar').setAttribute('aria-valuenow',Math.round(pct));
   345	    const rl=$('#treadmill-run-label');
