    r('rgba(255,255,255,0.12)', -2.5, -4.5 + bob, 5.0, 1.4);

    // Arms reaching toward desk (leaning forward slightly)
    r(shirt,    -5.0, -3.2 + bob, 2.0, 4.0);
    r(shirt,     3.0, -3.2 + bob, 2.0, 4.0);
